#include <bits/stdc++.h>
#define MOD 1000000007LL
using namespace std;
using ll = long long;
const int MAXK = 30;
const int MAXLOG = 200;

class Vec {
public:
    ll a[MAXK];
    Vec() { memset(a, 0, sizeof(a)); }
    Vec(const Vec&) = default;
    Vec& operator=(const Vec&) = default;
};

class Mat {
public:
    ll a[MAXK][MAXK];
    Mat() { memset(a, 0, sizeof(a)); }
    Mat(const Mat&) = default;
    Mat& operator=(const Mat&) = default;
    friend Mat operator*(const Mat& m1, const Mat& m2) {
        Mat m3;
        for (int i = 0; i < k; ++i)
            for (int j = 0; j < k; ++j)
                for (int l = 0; l < k; ++l)
                    m3.a[i][j] = (m3.a[i][j] + m1.a[i][l] * m2.a[l][j]) % MOD;
        return m3;
    }
    friend Vec operator*(const Mat& m, const Vec& v) {
        Vec v2;
        for (int i = 0; i < k; ++i)
            for (int j = 0; j < k; ++j)
                v2.a[i] = (v2.a[i] + v.a[j] * m.a[i][j]) % MOD;
        return v2;
    }
};

ll n, k;
Mat M[MAXK], MI[MAXK];
Mat E[MAXLOG][MAXK], EI[MAXLOG][MAXK];
Vec cur;

ll val(ll um) {
    if (um < k) return um;
    return (um + val(um / k)) % k;
}

void pre_comp() {
    for (int i = 0; i < k; ++i) {
        E[0][i] = M[i];
        EI[0][i] = MI[i];
    }
    int LOG = 0;
    ll t = n;
    while (t > 0) { ++LOG; t /= k; }
    for (int j = 1; j <= LOG; ++j) {
        E[j][0] = E[j-1][0];
        EI[j][0] = EI[j-1][0];
        for (int l = 1; l < k; ++l) {
            E[j][0] = E[j-1][l] * E[j][0];
            EI[j][0] = EI[j][0] * EI[j-1][l];
        }
        for (int i = 1; i < k; ++i) {
            E[j][i] = E[j-1][i-1] * (E[j][i-1] * EI[j-1][i-1]);
            EI[j][i] = E[j-1][i-1] * (EI[j][i-1] * EI[j-1][i-1]);
        }
    }
}

Vec solve(ll n, Vec v, int at) {
    if (n == 0) return v;
    int w = val(n / k);
    v = solve(n / k, v, at + 1);
    for (int i = 0; i < n % k; ++i) {
        v = E[at][(w + i) % k] * v;
    }
    return v;
}

int main() {
    scanf("%lld %lld", &n, &k);
    for (int i = 0; i < k; ++i) {
        cur.a[i] = 1;
        for (int j = 0; j < k; ++j) {
            for (int l = 0; l < k; ++l) {
                if (j == l) {
                    M[i].a[j][l] = 1;
                    MI[i].a[j][l] = 1;
                } else if (j == i) {
                    M[i].a[j][l] = 1;
                    MI[i].a[j][l] = -1;
                } else {
                    M[i].a[j][l] = 0;
                    MI[i].a[j][l] = 0;
                }
            }
        }
    }
    pre_comp();
    cur = solve(n, cur, 0);
    ll tot = 0;
    for (int i = 0; i < k; ++i) tot += cur.a[i];
    --tot;
    tot %= MOD;
    if (tot < 0) tot += MOD;
    while (tot % (k - 1) != 0) tot += MOD;
    printf("%lld\n", tot / (k - 1));
    return 0;
}
